mapper.select:
select con.Con_Name as conName, con.Con_Code as conCode,
c1.C_Name_History as encrProposeNameHistory, c1.C_Name as encrProposeName, c1.C_Abbreviation as encrProposeAbbName, mn.* from Con_Encr mn left join Con_Contract con on con.Con_Id=mn.Con_Id
left join SYS_Company c1 on mn.Encr_Propose_Id=c1.C_Id
${params.authSql}
where 1=1
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Encr_Create_Time desc
